-- v3.0-RTI WP06: formula registry, account roles + COA mapping, posting rules, accounting event outbox, journal links, close runs.
-- GENERATED by scripts/rti/build-migrations.cjs. Journals continue to be stored in india_gl_journals/india_gl_lines (0035).
CREATE TABLE india_formula_registry(
 id TEXT NOT NULL,version INTEGER NOT NULL,name TEXT NOT NULL,effective_from TEXT NOT NULL,owner_role TEXT NOT NULL,
 reference TEXT NOT NULL,verify INTEGER NOT NULL CHECK(verify IN (0,1)),tests_json TEXT NOT NULL CHECK(json_valid(tests_json)),
 status TEXT NOT NULL DEFAULT 'approved' CHECK(status IN ('pending','approved','retired')),PRIMARY KEY(id,version)
);
CREATE TRIGGER india_formula_registry_immutable BEFORE UPDATE ON india_formula_registry
WHEN NEW.id IS NOT OLD.id OR NEW.version IS NOT OLD.version OR NEW.tests_json IS NOT OLD.tests_json OR NEW.effective_from IS NOT OLD.effective_from
BEGIN SELECT RAISE(ABORT,'FORMULA_VERSION_IMMUTABLE'); END;
CREATE TABLE india_account_roles(
 role TEXT PRIMARY KEY,default_code TEXT NOT NULL,name TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN ('asset','liability','equity','revenue','expense')),
 required_dims_json TEXT NOT NULL CHECK(json_valid(required_dims_json))
);
CREATE TABLE india_account_role_map(
 tenant_id TEXT NOT NULL,legal_entity_id TEXT NOT NULL,role TEXT NOT NULL REFERENCES india_account_roles(role),
 account_code TEXT NOT NULL,gl_account_id TEXT,valid_from TEXT NOT NULL,valid_to TEXT,approved_by TEXT NOT NULL,
 PRIMARY KEY(tenant_id,legal_entity_id,role,valid_from)
);
CREATE TABLE india_posting_rules(
 id TEXT NOT NULL,version INTEGER NOT NULL,event_type TEXT NOT NULL,rule_json TEXT NOT NULL CHECK(json_valid(rule_json)),
 effective_from TEXT NOT NULL,effective_to TEXT,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','retired')),
 maker TEXT NOT NULL COLLATE NOCASE,checker TEXT COLLATE NOCASE,PRIMARY KEY(id,version),
 CHECK(checker IS NULL OR lower(checker)!=lower(maker)),CHECK(status!='approved' OR checker IS NOT NULL)
);
CREATE TRIGGER india_posting_rules_immutable BEFORE UPDATE ON india_posting_rules
WHEN OLD.status!='pending' AND (NEW.rule_json IS NOT OLD.rule_json OR NEW.event_type IS NOT OLD.event_type OR NEW.effective_from IS NOT OLD.effective_from)
BEGIN SELECT RAISE(ABORT,'POSTING_RULE_IMMUTABLE'); END;
CREATE TABLE india_accounting_events(
 tenant_id TEXT NOT NULL,id TEXT NOT NULL,event_type TEXT NOT NULL,legal_entity_id TEXT NOT NULL,period TEXT NOT NULL CHECK(period GLOB '20[0-9][0-9]-[0-1][0-9]'),
 occurred_on TEXT NOT NULL,currency TEXT NOT NULL DEFAULT 'IDR',amounts_json TEXT NOT NULL CHECK(json_valid(amounts_json)),
 dimensions_json TEXT NOT NULL CHECK(json_valid(dimensions_json)),source_type TEXT NOT NULL,source_id TEXT NOT NULL,
 idempotency_key TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','posted','exception')),
 journal_id TEXT,error_code TEXT,attempts INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,posted_at TEXT,
 PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,idempotency_key)
);
CREATE INDEX india_accounting_events_queue ON india_accounting_events(tenant_id,status,created_at);
CREATE TRIGGER india_accounting_events_guard BEFORE UPDATE ON india_accounting_events
WHEN NEW.tenant_id IS NOT OLD.tenant_id OR NEW.id IS NOT OLD.id OR NEW.event_type IS NOT OLD.event_type OR NEW.amounts_json IS NOT OLD.amounts_json
 OR NEW.dimensions_json IS NOT OLD.dimensions_json OR NEW.idempotency_key IS NOT OLD.idempotency_key OR NEW.legal_entity_id IS NOT OLD.legal_entity_id
 OR NEW.period IS NOT OLD.period OR OLD.status='posted'
BEGIN SELECT RAISE(ABORT,'ACCOUNTING_EVENT_IMMUTABLE'); END;
CREATE TRIGGER india_accounting_events_no_delete BEFORE DELETE ON india_accounting_events BEGIN SELECT RAISE(ABORT,'ACCOUNTING_EVENT_IMMUTABLE'); END;
CREATE TABLE india_gl_journal_links(
 tenant_id TEXT NOT NULL,journal_id TEXT NOT NULL,event_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('primary','auto_reverse','reversal')),
 rule_id TEXT NOT NULL,rule_version INTEGER NOT NULL,reversal_of_id TEXT,reason TEXT,
 PRIMARY KEY(tenant_id,journal_id),UNIQUE(tenant_id,event_id,kind),
 FOREIGN KEY(tenant_id,journal_id) REFERENCES india_gl_journals(tenant_id,id),
 CHECK(kind='primary' OR (reversal_of_id IS NOT NULL AND length(coalesce(reason,''))>=12))
);
CREATE TRIGGER india_gl_journal_links_immutable BEFORE UPDATE ON india_gl_journal_links BEGIN SELECT RAISE(ABORT,'JOURNAL_LINK_IMMUTABLE'); END;
CREATE TRIGGER india_gl_journal_links_no_delete BEFORE DELETE ON india_gl_journal_links BEGIN SELECT RAISE(ABORT,'JOURNAL_LINK_IMMUTABLE'); END;
CREATE TABLE india_close_runs(
 tenant_id TEXT NOT NULL,legal_entity_id TEXT NOT NULL,period TEXT NOT NULL,cycle TEXT NOT NULL CHECK(cycle IN ('MONTHLY','QUARTERLY','SEMIANNUAL','ANNUAL')),
 status TEXT NOT NULL DEFAULT 'PRELIMINARY' CHECK(status IN ('PRELIMINARY','SOFT_CLOSED','HARD_CLOSED','AUDITED','RESTATED')),
 checklist_json TEXT NOT NULL CHECK(json_valid(checklist_json)),preparer TEXT COLLATE NOCASE,approver TEXT COLLATE NOCASE,
 reopened_by TEXT COLLATE NOCASE,reopen_reason TEXT,pack_sha256 TEXT CHECK(pack_sha256 IS NULL OR length(pack_sha256)=64),
 version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(tenant_id,legal_entity_id,period),
 CHECK(approver IS NULL OR preparer IS NULL OR lower(approver)!=lower(preparer)),
 CHECK(status!='RESTATED' OR (reopened_by IS NOT NULL AND length(coalesce(reopen_reason,''))>=20))
);
CREATE TRIGGER india_close_runs_flow BEFORE UPDATE ON india_close_runs
WHEN NEW.version!=OLD.version+1 OR NEW.tenant_id IS NOT OLD.tenant_id OR NEW.legal_entity_id IS NOT OLD.legal_entity_id OR NEW.period IS NOT OLD.period
 OR NOT ((OLD.status='PRELIMINARY' AND NEW.status IN ('PRELIMINARY','SOFT_CLOSED'))
      OR (OLD.status='SOFT_CLOSED' AND NEW.status IN ('SOFT_CLOSED','HARD_CLOSED') AND (NEW.status!='HARD_CLOSED' OR NOT EXISTS(SELECT 1 FROM json_each(NEW.checklist_json) c WHERE c.value!='done')))
      OR (OLD.status='HARD_CLOSED' AND NEW.status IN ('AUDITED','RESTATED'))
      OR (OLD.status='RESTATED' AND NEW.status IN ('SOFT_CLOSED','HARD_CLOSED')))
BEGIN SELECT RAISE(ABORT,'CLOSE_TRANSITION_INVALID'); END;
CREATE TABLE india_report_cycle_definitions(
 id TEXT PRIMARY KEY,name TEXT NOT NULL,owner_role TEXT NOT NULL,cycle TEXT NOT NULL CHECK(cycle IN ('DAILY','WEEKLY','MONTHLY','QUARTERLY','SEMIANNUAL','ANNUAL')),
 formats_json TEXT NOT NULL CHECK(json_valid(formats_json)),recipients_json TEXT NOT NULL CHECK(json_valid(recipients_json)),
 classification TEXT NOT NULL CHECK(classification IN ('INTERNAL','CONFIDENTIAL','RESTRICTED')),schedule TEXT NOT NULL,sign_off_json TEXT NOT NULL CHECK(json_valid(sign_off_json))
);
CREATE TABLE india_report_snapshots(
 tenant_id TEXT NOT NULL,id TEXT NOT NULL,report_id TEXT NOT NULL REFERENCES india_report_cycle_definitions(id),period TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('PRELIMINARY','SOFT_CLOSED','HARD_CLOSED','AUDITED','RESTATED')),sha256 TEXT NOT NULL CHECK(length(sha256)=64),
 vault_reference TEXT NOT NULL,published_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,id)
);
CREATE TRIGGER india_report_snapshots_immutable BEFORE UPDATE ON india_report_snapshots BEGIN SELECT RAISE(ABORT,'REPORT_SNAPSHOT_IMMUTABLE'); END;
CREATE TRIGGER india_report_snapshots_no_delete BEFORE DELETE ON india_report_snapshots BEGIN SELECT RAISE(ABORT,'REPORT_SNAPSHOT_IMMUTABLE'); END;
